"""matplotlib.colorbar — colorbar shim with real state tracking.

The plotly backend draws colorbars itself (via ``showscale=True`` on the
trace), so this class doesn't render anything — but it tracks the same
state upstream tracks (label, ticks, formatter, locator, alpha, vmin/
vmax cache) so callers that introspect a colorbar get back real values.
"""

from matplotlib.artist import Artist


class Colorbar:
    """Colorbar attached to a ScalarMappable. State-only — actual
    rendering happens via plotly's built-in colorbar."""

    def __init__(self, ax, mappable=None, **kwargs):
        self.ax = ax
        self.mappable = mappable
        self.solids = None
        self._label = ''
        self._label_kwargs = {}
        self._ticks = None
        self._ticklabels = None
        self._alpha = kwargs.get('alpha', None)
        self._orientation = kwargs.get('orientation', 'vertical')
        self._extend = kwargs.get('extend', 'neither')
        # Cached values pulled from the mappable's clim.
        self._vmin_cache = None
        self._vmax_cache = None
        if mappable is not None:
            try:
                self._vmin_cache, self._vmax_cache = mappable.get_clim()
            except Exception:
                pass

    def set_label(self, label, *, loc=None, **kwargs):
        self._label = str(label) if label is not None else ''
        if loc is not None: kwargs['loc'] = loc
        self._label_kwargs = kwargs

    def set_ticks(self, ticks, *, labels=None, minor=False, **kwargs):
        self._ticks = list(ticks) if ticks is not None else None
        if labels is not None:
            self._ticklabels = [str(l) for l in labels]

    def set_ticklabels(self, ticklabels, *, minor=False, **kwargs):
        self._ticklabels = [str(l) for l in (ticklabels or [])]

    def update_normal(self, mappable):
        """Re-pull clim from the mappable. Mirrors upstream."""
        self.mappable = mappable
        if mappable is not None:
            try:
                self._vmin_cache, self._vmax_cache = mappable.get_clim()
            except Exception:
                pass

    def update_ticks(self):
        """No-op in the plotly backend — plotly redraws ticks itself."""
        return None

    def remove(self):
        """Detach from the parent figure. The plotly trace's
        ``showscale`` field controls visibility, not this object."""
        return None

    def set_alpha(self, alpha):
        self._alpha = alpha

    def get_alpha(self):
        return self._alpha

    @property
    def vmin(self):
        if self._vmin_cache is not None: return float(self._vmin_cache)
        if self.mappable is not None:
            try:
                lo, _ = self.mappable.get_clim()
                if lo is not None: return float(lo)
            except Exception: pass
        return 0.0

    @property
    def vmax(self):
        if self._vmax_cache is not None: return float(self._vmax_cache)
        if self.mappable is not None:
            try:
                _, hi = self.mappable.get_clim()
                if hi is not None: return float(hi)
            except Exception: pass
        return 1.0


class ColorbarBase(Colorbar):
    """Compatibility alias — upstream uses ColorbarBase as the parent
    of the renderer-coupled Colorbar; in the shim they're the same."""
    pass


def make_axes(parents, *, location=None, orientation=None, fraction=0.15,
              shrink=1.0, aspect=20, **kwargs):
    """Build the axes that holds the colorbar. The plotly backend
    doesn't carve out a separate axes — plotly's colorbar lives next
    to the trace — but we still return a placeholder so callers that
    inspect ``(cax, kwargs)`` get sensible values."""
    return None, dict(orientation=orientation or 'vertical',
                       fraction=fraction, shrink=shrink, aspect=aspect)


def make_axes_gridspec(parent, *, location=None, orientation=None,
                        fraction=0.15, shrink=1.0, aspect=20, **kwargs):
    """Gridspec-aware variant of :func:`make_axes`. Identical return
    shape — the plotly backend doesn't use gridspec for colorbar layout."""
    return None, dict(orientation=orientation or 'vertical',
                       fraction=fraction, shrink=shrink, aspect=aspect)


# ─── Locator/formatter accessors (state-only) ───────────────────────


def _cb_add_lines(self, levels=None, colors=None, linewidths=None, *,
                  erase=True):
    """Overlay constant-value lines on the colorbar. Returns a
    :class:`LineCollection`-shaped object so callers can introspect."""
    from matplotlib.collections import LineCollection
    if levels is None: return None
    segs = [[(0.0, lv), (1.0, lv)] for lv in levels]
    lc = LineCollection(segs)
    if colors is not None: lc.set_edgecolor(colors)
    if linewidths is not None: lc.set_linewidth(linewidths)
    self.solids = lc
    return lc


def _cb_drag_pan(self, button, key, x, y): pass


def _cb_get_ticks(self, minor=False):
    """Return the major (or minor) tick positions actually used."""
    if not minor and self._ticks is not None:
        return list(self._ticks)
    loc = self.locator if not minor else self.minorlocator
    if loc is None: return []
    try:
        return list(loc.tick_values(self.vmin, self.vmax))
    except Exception:
        return []


def _cb_formatter_get(self):
    from matplotlib.ticker import ScalarFormatter
    return getattr(self, '_formatter', None) or ScalarFormatter()


def _cb_formatter_set(self, v): self._formatter = v


def _cb_locator_get(self):
    from matplotlib.ticker import AutoLocator, LogLocator
    if 'log' in str(getattr(self.mappable, 'norm', '')).lower():
        return getattr(self, '_locator', None) or LogLocator()
    return getattr(self, '_locator', None) or AutoLocator()


def _cb_locator_set(self, v): self._locator = v


def _cb_minorformatter_get(self): return getattr(self, '_minorformatter', None)
def _cb_minorformatter_set(self, v): self._minorformatter = v


def _cb_minorlocator_get(self): return getattr(self, '_minorlocator', None)
def _cb_minorlocator_set(self, v): self._minorlocator = v


def _cb_minorticks_off(self):
    from matplotlib.ticker import NullLocator
    self._minorlocator = NullLocator()


def _cb_minorticks_on(self):
    from matplotlib.ticker import AutoMinorLocator
    self._minorlocator = AutoMinorLocator()


Colorbar.add_lines          = _cb_add_lines
Colorbar.drag_pan           = _cb_drag_pan
Colorbar.get_ticks          = _cb_get_ticks
Colorbar.formatter          = property(_cb_formatter_get, _cb_formatter_set)
Colorbar.locator            = property(_cb_locator_get, _cb_locator_set)
Colorbar.minorformatter     = property(_cb_minorformatter_get, _cb_minorformatter_set)
Colorbar.minorlocator       = property(_cb_minorlocator_get, _cb_minorlocator_set)
Colorbar.minorticks_off     = _cb_minorticks_off
Colorbar.minorticks_on      = _cb_minorticks_on


# Class-level attribute for upstream compatibility (n_rasterize is a
# private upstream constant controlling when to switch from vector
# to raster representation — we never rasterize, so 50 matches upstream
# default without ever triggering).
Colorbar.n_rasterize = 50
